import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Community Support","description":"","frontmatter":{},"headers":[],"relativePath":"community-support.md","filePath":"community-support.md"}'),i={name:"community-support.md"};function n(s,e,d,l,u,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="community-support" tabindex="-1">Community Support <a class="header-anchor" href="#community-support" aria-label="Permalink to &quot;Community Support&quot;">​</a></h1><p>Tradeboard is community supported. There is no vendor helpdesk and no paid support tier: help comes from other traders and developers running the same software, and from the maintainers when they have time.</p><h3 id="where-to-get-help" tabindex="-1">Where to Get Help <a class="header-anchor" href="#where-to-get-help" aria-label="Permalink to &quot;Where to Get Help&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Channel</th><th>Use it for</th><th>Link</th></tr></thead><tbody><tr><td>Discord</td><td>Questions, setup problems, strategy discussion, release news</td><td><a href="https://www.tradeboard.in/discord" target="_blank" rel="noreferrer">https://www.tradeboard.in/discord</a></td></tr><tr><td>GitHub Issues</td><td>Reproducible bugs and feature requests</td><td><a href="https://github.com/wesoftcorp/tradeboard/issues" target="_blank" rel="noreferrer">github.com/marketcalls/tradeboard/issues</a></td></tr><tr><td>GitHub Discussions</td><td>Open-ended questions that are not bugs</td><td><a href="https://github.com/wesoftcorp/tradeboard/discussions" target="_blank" rel="noreferrer">github.com/marketcalls/tradeboard/discussions</a></td></tr><tr><td>X (Twitter)</td><td>Announcements</td><td><a href="https://twitter.com/tradeboardHQ" target="_blank" rel="noreferrer">@tradeboardHQ</a></td></tr></tbody></table><p><strong>Security issues are the exception.</strong> Do not report a vulnerability in a public channel. Email <code>rajandran@tradeboard.in</code> instead, as described in the repository&#39;s <code>SECURITY.md</code>.</p><h3 id="community-guidelines" tabindex="-1">Community Guidelines <a class="header-anchor" href="#community-guidelines" aria-label="Permalink to &quot;Community Guidelines&quot;">​</a></h3><ul><li><strong>Respect:</strong> Treat every member with respect. No harassment or discrimination is tolerated.</li><li><strong>Collaboration:</strong> Feel free to ask for help and offer support. Share your knowledge and learn from others.</li><li><strong>No Spam:</strong> Keep discussions on-topic. Avoid spamming channels with promotions or irrelevant content.</li><li><strong>No paid signal selling:</strong> Tradeboard is execution infrastructure, not a marketplace. Do not use the community to sell strategies or tips.</li><li><strong>Intellectual Property:</strong> Respect copyright laws and do not share illegal downloads or copyrighted content.</li><li><strong>Privacy:</strong> Do not share personal information of yourself or others. Never paste an API key, a broker credential, or the contents of your <code>.env</code> file into a public channel or a GitHub issue.</li></ul><h3 id="asking-a-question-that-gets-answered" tabindex="-1">Asking a Question That Gets Answered <a class="header-anchor" href="#asking-a-question-that-gets-answered" aria-label="Permalink to &quot;Asking a Question That Gets Answered&quot;">​</a></h3><p>Tradeboard runs on your own machine against your own broker, so nobody else can see what went wrong. Include:</p><ul><li>your Tradeboard version, from the dashboard footer or <code>pyproject.toml</code>;</li><li>your operating system and Python version;</li><li>the broker plugin you are connected to;</li><li>what you expected and what actually happened;</li><li>the relevant lines from <code>log/</code>, with API keys and order IDs redacted.</li></ul><p>&quot;It does not work&quot; cannot be answered. A log excerpt usually can.</p><h3 id="before-you-ask" tabindex="-1">Before You Ask <a class="header-anchor" href="#before-you-ask" aria-label="Permalink to &quot;Before You Ask&quot;">​</a></h3><p>Most questions are already answered:</p><ul><li><a href="./README">What is Tradeboard?</a> for scope and boundaries</li><li><a href="./getting-started/README">Getting Started</a> for installation</li><li><a href="./api-documentation/v1/README">API Documentation</a> for the REST and WebSocket contract</li><li><a href="./symbol-format">Symbol Format</a> for how symbols are constructed</li><li><a href="./responsibilities">Responsibilities</a> for what you are expected to own</li><li><a href="./contributors">Contributors</a> for the development setup</li></ul><p>Search the existing GitHub issues too. A bug you hit today has often been reported, and sometimes fixed, already.</p><h3 id="contributing-back" tabindex="-1">Contributing Back <a class="header-anchor" href="#contributing-back" aria-label="Permalink to &quot;Contributing Back&quot;">​</a></h3><p>The community works because people give as well as take. Useful contributions include reporting a reproducible bug, improving a documentation page, adding a broker plugin, and answering someone else&#39;s question on Discord. See <a href="./contributors">Contributors</a> for the development setup and pull-request conventions.</p><h3 id="what-support-does-not-cover" tabindex="-1">What Support Does Not Cover <a class="header-anchor" href="#what-support-does-not-cover" aria-label="Permalink to &quot;What Support Does Not Cover&quot;">​</a></h3><ul><li>Guaranteed response times, including during market hours.</li><li>Debugging your trading strategy or its profitability.</li><li>Broker-side problems. Contact your broker for API entitlement, rate limits, static IP registration, and account issues.</li><li>Recovering money lost to a strategy, a misconfiguration, or an outage. See <a href="./responsibilities">Responsibilities</a>.</li></ul>',19)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
